/**
 * Deploy MoltenRegistry to Mantle Sepolia (chain 5003).
 *
 * Usage:
 *   DEPLOYER_PRIVATE_KEY=0x... npx tsx demo/deploy/deploy.ts
 *
 * Get Sepolia MNT from the Mantle faucet:
 *   https://faucet.sepolia.mantle.xyz
 */

import { createWalletClient, createPublicClient, http, defineChain } from "viem";
import { privateKeyToAccount } from "viem/accounts";

const mantleSepolia = defineChain({
  id: 5003,
  name: "Mantle Sepolia",
  nativeCurrency: { name: "MNT", symbol: "MNT", decimals: 18 },
  rpcUrls: {
    default: { http: [process.env["MANTLE_SEPOLIA_RPC_URL"] ?? "https://rpc.sepolia.mantle.xyz"] },
  },
  blockExplorers: {
    default: { name: "Mantle Sepolia Explorer", url: "https://explorer.sepolia.mantle.xyz" },
  },
  testnet: true,
});

const BYTECODE =
  "" as `0x${string}`;

const ABI = [
  { inputs: [], stateMutability: "nonpayable", type: "constructor" },
  {
    anonymous: false,
    inputs: [
      { indexed: true, internalType: "string", name: "tool", type: "string" },
      { indexed: true, internalType: "address", name: "caller", type: "address" },
    ],
    name: "ToolUsed",
    type: "event",
  },
  { inputs: [], name: "DESCRIPTION", outputs: [{ internalType: "string", name: "", type: "string" }], stateMutability: "view", type: "function" },
  { inputs: [], name: "NAME", outputs: [{ internalType: "string", name: "", type: "string" }], stateMutability: "view", type: "function" },
  { inputs: [], name: "VERSION", outputs: [{ internalType: "string", name: "", type: "string" }], stateMutability: "view", type: "function" },
  { inputs: [], name: "deployedAt", outputs: [{ internalType: "uint256", name: "", type: "uint256" }], stateMutability: "view", type: "function" },
  { inputs: [], name: "deployer", outputs: [{ internalType: "address", name: "", type: "address" }], stateMutability: "view", type: "function" },
  {
    inputs: [],
    name: "identity",
    outputs: [
      { internalType: "string", name: "", type: "string" },
      { internalType: "string", name: "", type: "string" },
      { internalType: "string", name: "", type: "string" },
    ],
    stateMutability: "pure",
    type: "function",
  },
  { inputs: [{ internalType: "string", name: "tool", type: "string" }], name: "recordToolCall", outputs: [], stateMutability: "nonpayable", type: "function" },
  { inputs: [{ internalType: "string", name: "", type: "string" }], name: "toolCallCount", outputs: [{ internalType: "uint256", name: "", type: "uint256" }], stateMutability: "view", type: "function" },
  { inputs: [], name: "totalCalls", outputs: [{ internalType: "uint256", name: "", type: "uint256" }], stateMutability: "view", type: "function" },
] as const;

async function main() {
  const privateKey = process.env["DEPLOYER_PRIVATE_KEY"];
  if (!privateKey) throw new Error("DEPLOYER_PRIVATE_KEY not set");

  const account = privateKeyToAccount(privateKey as `0x${string}`);

  const walletClient = createWalletClient({
    account,
    chain: mantleSepolia,
    transport: http(),
  });

  const publicClient = createPublicClient({
    chain: mantleSepolia,
    transport: http(),
  });

  console.log(`Deploying MoltenRegistry from ${account.address}...`);

  const hash = await walletClient.deployContract({
    abi: ABI,
    bytecode: BYTECODE,
  });

  console.log(`Tx hash: ${hash}`);
  console.log("Waiting for confirmation...");

  const receipt = await publicClient.waitForTransactionReceipt({ hash });

  console.log(`\n✅ MoltenRegistry deployed!`);
  console.log(`Contract address: ${receipt.contractAddress}`);
  console.log(`Explorer: https://explorer.sepolia.mantle.xyz/address/${receipt.contractAddress}`);
  console.log(`\nUpdate SUBMISSION.md and X thread with this address.`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
